  'WIZ-EQP-01': { auto: true, mods: { spellAtk: 1 }, capStats: { atk: 1 } },
  'WIZ-EQP-02': { auto: true, triggers: [{ on: 'hitDmg', cond: 'emberWand', per: 'round', dmg: 1 }] },
  'WIZ-EQP-03': { auto: true, mods: { spellCheck: 1 }, capStats: { skill: 1 } },
  'WIZ-EQP-04': { auto: true, stats: { life: 1 } },
  'WIZ-EQP-05': { auto: true, stats: { res: 1 }, mods: { rangedAtkVsMe: -1 } },
  'WIZ-EQP-06': { auto: true, stats: { tough: 1 } },
  'WIZ-EQP-07': { auto: true, activate: { phase: 'turn', per: 'fight', label: 'Mana Potion: cast 1 extra spell', do: [['extraCast', 1]] } },
  'WIZ-EQP-08': { auto: true, activate: { phase: 'turn', per: 'fight', label: 'Healing Scroll: heal 2 (Range 3)', usesAction: true, do: [['pickAlly', 3, [['healT', 2]]]] } },
  // v1.10.2: the scrolls still cast the OLD Fireball / Chain Lightning (whether they cast the II versions is OPEN for the user);
  // the old spells live on as scroll-only cards WIZ-SPL-14L / WIZ-SPL-18L (js/cards_patch.js), effects unchanged from v1.10.1.
  'WIZ-EQP-09': { auto: true, activate: { phase: 'turn', per: 'fight', label: 'Fire Scroll: cast Fireball', usesAction: true, do: [['castFree', 'WIZ-SPL-14L']] } },
  'WIZ-EQP-10': { auto: true, activate: { phase: 'turn', per: 'fight', label: 'Lightning Scroll: cast Chain Lightning', usesAction: true, do: [['castFree', 'WIZ-SPL-18L']] } },
